import { useEffect, useState, useRef } from 'react'
import { Card, Select, Spin, Statistic, Row, Col, Alert } from 'antd'
import { TableOutlined, DatabaseOutlined } from '@ant-design/icons'
import mermaid from 'mermaid'
import DOMPurify from 'dompurify'
import {
  getSchemaMermaid,
  getSchemaStats,
  type SchemaStats,
} from '../services/api'

interface StarSchemaProps {
  level?: 'overview' | 'detailed'
}

function StarSchema({ level: initialLevel = 'overview' }: StarSchemaProps) {
  const [level, setLevel] = useState<'overview' | 'detailed'>(initialLevel)
  const [mermaidCode, setMermaidCode] = useState<string>('')
  const [stats, setStats] = useState<SchemaStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const diagramRef = useRef<HTMLDivElement>(null)

  // 初始化 Mermaid（設定 securityLevel 防止 XSS）
  useEffect(() => {
    mermaid.initialize({
      startOnLoad: false,
      theme: 'default',
      securityLevel: 'strict',
      er: {
        useMaxWidth: true,
        layoutDirection: 'TB',
      },
    })
  }, [])

  // 載入資料
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true)
      setError(null)
      try {
        const [mermaidRes, statsRes] = await Promise.all([
          getSchemaMermaid(level),
          getSchemaStats(),
        ])
        setMermaidCode(mermaidRes.mermaid)
        setStats(statsRes)
      } catch (err) {
        setError('載入星狀模型失敗')
        console.error(err)
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [level])

  // 渲染 Mermaid 圖表（使用 DOMPurify 防止 XSS）
  useEffect(() => {
    if (mermaidCode && diagramRef.current) {
      const renderDiagram = async () => {
        try {
          // 使用 textContent 清空比 innerHTML 更安全
          diagramRef.current!.textContent = ''
          const diagramId = `star-schema-${level}-${Date.now()}`
          const { svg } = await mermaid.render(diagramId, mermaidCode)
          // 使用 DOMPurify sanitize SVG 防止 XSS
          diagramRef.current!.innerHTML = DOMPurify.sanitize(svg, {
            USE_PROFILES: { svg: true, svgFilters: true },
          })
        } catch (err) {
          console.error('Mermaid 渲染失敗', err)
        }
      }
      renderDiagram()
    }
  }, [mermaidCode, level])

  const handleLevelChange = (value: 'overview' | 'detailed') => {
    setLevel(value)
  }

  if (error) {
    return <Alert type="error" message={error} />
  }

  return (
    <div>
      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
        <Col xs={12} sm={6}>
          <Card size="small">
            <Statistic
              title="總表格數"
              value={stats?.total_tables || 0}
              prefix={<TableOutlined />}
            />
          </Card>
        </Col>
        <Col xs={12} sm={6}>
          <Card size="small">
            <Statistic
              title="總記錄數"
              value={stats?.total_records || 0}
              prefix={<DatabaseOutlined />}
              formatter={(value) => value?.toLocaleString()}
            />
          </Card>
        </Col>
        <Col xs={12} sm={6}>
          <Card size="small">
            <Statistic
              title="事實表"
              value={Object.keys(stats?.fact_tables || {}).length}
              valueStyle={{ color: '#1890ff' }}
            />
          </Card>
        </Col>
        <Col xs={12} sm={6}>
          <Card size="small">
            <Statistic
              title="維度表"
              value={Object.keys(stats?.dim_tables || {}).length}
              valueStyle={{ color: '#52c41a' }}
            />
          </Card>
        </Col>
      </Row>

      <Card
        title="星狀模型圖"
        extra={
          <Select
            value={level}
            onChange={handleLevelChange}
            style={{ width: 120 }}
            options={[
              { value: 'overview', label: '概覽' },
              { value: 'detailed', label: '詳細' },
            ]}
          />
        }
      >
        <Spin spinning={loading}>
          <div
            ref={diagramRef}
            style={{
              minHeight: 400,
              overflow: 'auto',
              textAlign: 'center',
            }}
          />
        </Spin>
      </Card>
    </div>
  )
}

export default StarSchema
