import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Table, Card, Select, Tag, Space, Button, Spin, Alert } from 'antd'
import { EyeOutlined } from '@ant-design/icons'
import type { ColumnsType } from 'antd/es/table'
import {
  getPendingRecords,
  getTables,
  type PendingRecord,
  type TableInfo,
} from '../services/api'

// 表格名稱對照
const TABLE_NAMES: Record<string, string> = {
  '10': '品牌表',
  '20': '通路表',
  '30': '金流表',
  '40': '物流表',
  '41': '郵遞區號表',
  '50': '訂單表',
  '60': '客戶表',
  '70': '商品表',
  '80': '活動管理表',
  '99': '訂單明細表',
}

function PendingList() {
  const navigate = useNavigate()
  const [records, setRecords] = useState<PendingRecord[]>([])
  const [tables, setTables] = useState<TableInfo[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [selectedTable, setSelectedTable] = useState<string | undefined>()
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 20,
    total: 0,
  })

  const fetchRecords = async (page = 1, tableCode?: string) => {
    setLoading(true)
    try {
      const data = await getPendingRecords({
        table_code: tableCode,
        limit: pagination.pageSize,
        offset: (page - 1) * pagination.pageSize,
      })
      setRecords(data.records)
      setPagination((prev) => ({
        ...prev,
        current: page,
        total: data.total,
      }))
    } catch (err) {
      setError('載入待處理記錄失敗')
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    const fetchTables = async () => {
      try {
        const data = await getTables()
        setTables(data)
      } catch (err) {
        console.error('載入表格列表失敗', err)
      }
    }
    fetchTables()
    fetchRecords()
  }, [])

  const handleTableChange = (value: string | undefined) => {
    setSelectedTable(value)
    fetchRecords(1, value)
  }

  const handlePageChange = (page: number) => {
    fetchRecords(page, selectedTable)
  }

  const columns: ColumnsType<PendingRecord> = [
    {
      title: '記錄 ID',
      dataIndex: 'record_id',
      key: 'record_id',
      width: 120,
      ellipsis: true,
    },
    {
      title: '表格',
      dataIndex: 'table_code',
      key: 'table_code',
      width: 120,
      render: (code: string) => TABLE_NAMES[code] || code,
    },
    {
      title: '違規數',
      dataIndex: 'violation_count',
      key: 'violation_count',
      width: 80,
      render: (count: number) => (
        <Tag color={count > 0 ? 'red' : 'green'}>
          {count || 0}
        </Tag>
      ),
    },
    {
      title: 'AI 信心度',
      dataIndex: 'confidence_score',
      key: 'confidence_score',
      width: 100,
      render: (score: number) => (
        <Tag color={score >= 0.8 ? 'green' : score >= 0.5 ? 'orange' : 'red'}>
          {(score * 100).toFixed(0)}%
        </Tag>
      ),
    },
    {
      title: '清洗時間',
      dataIndex: 'cleaned_at',
      key: 'cleaned_at',
      width: 180,
      render: (date: string) =>
        date ? new Date(date).toLocaleString('zh-TW') : '-',
    },
    {
      title: '操作',
      key: 'action',
      width: 100,
      render: (_, record) => (
        <Button
          type="link"
          icon={<EyeOutlined />}
          onClick={() => navigate(`/pending/${record.record_id}`)}
        >
          查看
        </Button>
      ),
    },
  ]

  if (error) {
    return <Alert type="error" message={error} />
  }

  return (
    <Card
      title="待處理清單"
      extra={
        <Space>
          <Select
            style={{ width: 150 }}
            placeholder="篩選表格"
            allowClear
            value={selectedTable}
            onChange={handleTableChange}
            options={tables.map((t) => ({
              value: t.code,
              label: t.name,
            }))}
          />
        </Space>
      }
    >
      <Spin spinning={loading}>
        <Table
          columns={columns}
          dataSource={records}
          rowKey="record_id"
          pagination={{
            ...pagination,
            onChange: handlePageChange,
            showSizeChanger: false,
            showTotal: (total) => `共 ${total} 筆`,
          }}
        />
      </Spin>
    </Card>
  )
}

export default PendingList
