import { useEffect, useState } from 'react'
import { Table, Card, Select, DatePicker, Space, Spin, Alert, Tag } from 'antd'
import type { ColumnsType } from 'antd/es/table'
import type { Dayjs } from 'dayjs'
import {
  getCorrectionHistory,
  getTables,
  type CorrectionHistory,
  type TableInfo,
} from '../services/api'

// 表格名稱對照
const TABLE_NAMES: Record<string, string> = {
  '10': '品牌表',
  '20': '通路表',
  '30': '金流表',
  '40': '物流表',
  '41': '郵遞區號表',
  '50': '訂單表',
  '60': '客戶表',
  '70': '商品表',
  '80': '活動管理表',
  '99': '訂單明細表',
}

const { RangePicker } = DatePicker

function History() {
  const [history, setHistory] = useState<CorrectionHistory[]>([])
  const [tables, setTables] = useState<TableInfo[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [selectedTable, setSelectedTable] = useState<string | undefined>()
  const [dateRange, setDateRange] = useState<[Dayjs | null, Dayjs | null]>([
    null,
    null,
  ])

  const fetchHistory = async (
    tableCode?: string,
    dates?: [Dayjs | null, Dayjs | null]
  ) => {
    setLoading(true)
    try {
      const params: {
        table_code?: string
        date_from?: string
        date_to?: string
        limit: number
      } = { limit: 100 }

      if (tableCode) {
        params.table_code = tableCode
      }
      if (dates && dates[0]) {
        params.date_from = dates[0].format('YYYY-MM-DD')
      }
      if (dates && dates[1]) {
        params.date_to = dates[1].format('YYYY-MM-DD')
      }

      const data = await getCorrectionHistory(params)
      setHistory(data)
    } catch (err) {
      setError('載入修正歷史失敗')
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    const fetchTables = async () => {
      try {
        const data = await getTables()
        setTables(data)
      } catch (err) {
        console.error('載入表格列表失敗', err)
      }
    }
    fetchTables()
    fetchHistory()
  }, [])

  const handleTableChange = (value: string | undefined) => {
    setSelectedTable(value)
    fetchHistory(value, dateRange)
  }

  const handleDateChange = (dates: [Dayjs | null, Dayjs | null] | null) => {
    const newDates: [Dayjs | null, Dayjs | null] = dates || [null, null]
    setDateRange(newDates)
    fetchHistory(selectedTable, newDates)
  }

  const columns: ColumnsType<CorrectionHistory> = [
    {
      title: '記錄 ID',
      dataIndex: 'record_id',
      key: 'record_id',
      width: 120,
      ellipsis: true,
    },
    {
      title: '表格',
      dataIndex: 'table_code',
      key: 'table_code',
      width: 120,
      render: (code: string) => TABLE_NAMES[code] || code,
    },
    {
      title: '修正時間',
      dataIndex: 'corrected_at',
      key: 'corrected_at',
      width: 180,
      render: (date: string) =>
        date ? new Date(date).toLocaleString('zh-TW') : '-',
    },
    {
      title: '修正者',
      dataIndex: 'corrected_by',
      key: 'corrected_by',
      width: 100,
      render: (by: string) => <Tag color="blue">{by || 'user'}</Tag>,
    },
  ]

  if (error) {
    return <Alert type="error" message={error} />
  }

  return (
    <Card
      title="修正歷史"
      extra={
        <Space>
          <Select
            style={{ width: 150 }}
            placeholder="篩選表格"
            allowClear
            value={selectedTable}
            onChange={handleTableChange}
            options={tables.map((t) => ({
              value: t.code,
              label: t.name,
            }))}
          />
          <RangePicker onChange={handleDateChange} />
        </Space>
      }
    >
      <Spin spinning={loading}>
        <Table
          columns={columns}
          dataSource={history}
          rowKey="record_id"
          pagination={{
            pageSize: 20,
            showTotal: (total) => `共 ${total} 筆`,
          }}
        />
      </Spin>
    </Card>
  )
}

export default History
