import { Routes, Route, Link, useLocation } from 'react-router-dom'
import { Layout, Menu, Typography } from 'antd'
import {
  DashboardOutlined,
  UnorderedListOutlined,
  HistoryOutlined,
  ApartmentOutlined,
} from '@ant-design/icons'
import Dashboard from './pages/Dashboard'
import PendingList from './pages/PendingList'
import CorrectionDetail from './pages/CorrectionDetail'
import History from './pages/History'
import StarSchemaPage from './pages/StarSchemaPage'

const { Header, Content, Sider } = Layout
const { Title } = Typography

function App() {
  const location = useLocation()

  const menuItems = [
    {
      key: '/',
      icon: <DashboardOutlined />,
      label: <Link to="/">儀表板</Link>,
    },
    {
      key: '/pending',
      icon: <UnorderedListOutlined />,
      label: <Link to="/pending">待處理清單</Link>,
    },
    {
      key: '/history',
      icon: <HistoryOutlined />,
      label: <Link to="/history">修正歷史</Link>,
    },
    {
      key: '/schema',
      icon: <ApartmentOutlined />,
      label: <Link to="/schema">星狀模型</Link>,
    },
  ]

  return (
    <Layout style={{ minHeight: '100vh' }}>
      <Sider theme="light" width={200}>
        <div style={{ padding: '16px', textAlign: 'center' }}>
          <Title level={4} style={{ margin: 0, color: '#1890ff' }}>
            RagicEDP
          </Title>
          <Typography.Text type="secondary">資料修正介面</Typography.Text>
        </div>
        <Menu
          mode="inline"
          selectedKeys={[location.pathname]}
          items={menuItems}
          style={{ borderRight: 0 }}
        />
      </Sider>
      <Layout>
        <Header style={{ background: '#fff', padding: '0 24px' }}>
          <Title level={4} style={{ margin: '16px 0' }}>
            資料修正介面
          </Title>
        </Header>
        <Content style={{ margin: '24px', minHeight: 280 }}>
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/pending" element={<PendingList />} />
            <Route path="/pending/:id" element={<CorrectionDetail />} />
            <Route path="/history" element={<History />} />
            <Route path="/schema" element={<StarSchemaPage />} />
          </Routes>
        </Content>
      </Layout>
    </Layout>
  )
}

export default App
